/**
 * Engine job contracts. Heavy work lives in per-job-type Web Workers
 * (wrapped with comlink). The main thread never blocks.
 */

/**
 * A PDF source. `File` is a disk-backed handle and structured-clones cheaply,
 * so large files are read inside the worker instead of copied on the main
 * thread first. ArrayBuffer stays supported for generated bytes and tests.
 */
export type PdfData = ArrayBuffer | File;

export type Progress = (p: number, label?: string) => void;

export type MergeInput = {
  files: { name: string; buffer: ArrayBuffer }[];
};
export type MergeOutput = { blob: Blob; pages: number };

export type SplitMode = "pick" | "every" | "ranges";
export type SplitInput =
  | { mode: "pick"; file: ArrayBuffer; pages: number[]; pageCount: number }
  | { mode: "every"; file: ArrayBuffer; pageCount: number }
  | { mode: "ranges"; file: ArrayBuffer; ranges: { start: number; end: number }[] };

export type SplitOutput = { blobs: { blob: Blob; name: string }[]; count: number };

export type RotateStep = { rotateBy: 90 | 180 | 270; pages: number[] | "all" };
export type RotateInput = { file: ArrayBuffer; steps: RotateStep[] };
export type RotateOutput = { blob: Blob };

export type RenameInput = { blobs: { blob: Blob; name: string }[]; stem: string };
export type RenameOutput = { blobs: { blob: Blob; name: string }[] };

export type CompressInput = {
  file: PdfData;
  fileName: string;
  target?: number | null; // bytes; null = squeeze as small as possible
  engine: "auto" | "flatten";
};
export type CompressOutput = {
  blob: Blob;
  before: number;
  after: number;
  engineUsed: "gs" | "flatten";
  attempts: { dpi: number; size: number }[];
  reached: boolean;
};

export type PdfToImageInput = {
  file: PdfData;
  format: "png" | "jpg" | "webp";
  quality: number; // 0..1
  scale: number; // dpi/72 multiplier derived from quality
  pages: number[] | "all";
};
export type PdfToImageOutput = { blobs: { blob: Blob; name: string }[] };

export type ImageToPdfInput = {
  images: { name: string; buffer: ArrayBuffer; type: string }[];
  pageSize: "fit" | "a4";
  margin: number; // 0..08 fraction each side (fit) or mm (a4 -> converted)
};
export type ImageToPdfOutput = { blob: Blob };

export type TextToPdfInput = { text: string; title?: string };
export type TextToPdfOutput = { blob: Blob; pages: number };

export type PdfInfoInput = { file: PdfData };
export type PdfInfoOutput = { pageCount: number; encrypted: boolean };

export type PdfInfoRangeInput = { file: ArrayBuffer; pages: number[]; width: number };
export type Thumb = { page: number; blobUrl?: string; blob: Blob };

export type SignPlaceInput = {
  file: PdfData;
  signaturePng: ArrayBuffer; // RGBA PNG bytes
  placements: {
    pageIndex: number;
    // Fraction of the page (top-left origin) — the worker converts to
    // PDF user units (bottom-left origin) using the real page size.
    x: number;
    y: number;
    width: number;
    height: number;
    rotation: number;
  }[];
};
export type SignPlaceOutput = { blob: Blob };

export type FlowStepConfig =
  | { type: "merge" }
  | { type: "compress"; target: number | null }
  | { type: "rotate"; steps: RotateStep[] }
  | { type: "rename"; stem: string };

/* ---------- page organizer ---------- */
/** One output page: copy `page` (1-based) from `source` and add `rotation` degrees. */
export type OrganizePage = { source: number; page: number; rotation: number };
export type OrganizeInput = { sources: PdfData[]; pages: OrganizePage[] };
export type OrganizeOutput = { blob: Blob; pages: number };

/* ---------- metadata / sanitizer ---------- */
export type PdfMetadataFields = {
  title: string;
  author: string;
  subject: string;
  keywords: string;
  creator: string;
  producer: string;
  creationDate: string;
  modificationDate: string;
};

export type PdfRiskReport = {
  javascript: number;
  embeddedFiles: number;
  openAction: number;
  launch: number;
  uri: number;
  annotations: number;
  xmp: boolean;
  acroForm: boolean;
  xfa: boolean;
};

export type PdfFontInfo = {
  /** BaseFont name without the subset prefix, e.g. "Arial" or "Arial,Bold". */
  name: string;
  /** PDF font subtype, e.g. "TrueType", "Type0", "Type1". */
  type: string;
  /** Whether the file carries the font program itself. */
  embedded: boolean;
  /** Subset fonts usually have a six-letter prefix in the raw name. */
  subset: boolean;
  /** How many pages reference this font through their resources. */
  pages: number;
};

export type PdfSignatureInfo = {
  field: string;
  kind: "signature" | "certification" | "field";
  signed: boolean;
  subFilter: string;
  byteRange: number[];
  /** The signed byte ranges still cover the file up to EOF. */
  coversWholeFile: boolean;
  /** Bytes exist after the signed ranges, so the file changed after signing. */
  modifiedAfterSigning: boolean;
  signedAt: string;
  name: string;
  reason: string;
  location: string;
};

export type PdfMetadataInput = { file: PdfData };
export type PdfMetadataOutput = {
  pageCount: number;
  size: number;
  metadata: PdfMetadataFields;
  risks: PdfRiskReport;
};
export type PdfMetadataWriteInput = { file: PdfData; metadata: Partial<PdfMetadataFields> };
export type PdfMetadataWriteOutput = { blob: Blob; metadata: PdfMetadataFields };

export type PdfInspectInput = { file: PdfData };
export type PdfInspectOutput = {
  pageCount: number;
  size: number;
  metadata: PdfMetadataFields;
  risks: PdfRiskReport;
  fonts: PdfFontInfo[];
  embeddedFiles: string[];
  signatures: PdfSignatureInfo[];
};

export type PdfSanitizeInput = { file: PdfData };
export type PdfSanitizeOutput = {
  blob: Blob;
  before: number;
  after: number;
  removed: PdfRiskReport;
  /** A second scan of the rebuilt bytes, so the result is checkable. */
  afterRisks: PdfRiskReport;
};

/* ---------- verify / compare ---------- */
export type PdfFileSummary = {
  name: string;
  size: number;
  pageCount: number;
  sha256: string;
  sha1: string;
  sha512: string;
  metadata: PdfMetadataFields;
  signatures: PdfSignatureInfo[];
  fonts: PdfFontInfo[];
  risks: PdfRiskReport;
};

export type PdfVerifyInput = { file: PdfData; name?: string };
export type PdfVerifyOutput = PdfFileSummary;

export type PdfCompareInput = {
  a: PdfData;
  b: PdfData;
  aName: string;
  bName: string;
};
export type PdfComparePage = {
  page: number;
  status: "same" | "changed" | "only-a" | "only-b";
};
export type PdfCompareMetadataChange = {
  field: keyof PdfMetadataFields;
  a: string;
  b: string;
};
export type PdfCompareOutput = {
  identical: boolean;
  a: PdfFileSummary;
  b: PdfFileSummary;
  pages: PdfComparePage[];
  metadataChanges: PdfCompareMetadataChange[];
};

/* ---------- PDF text / markdown ---------- */
export type PdfTextFormat = "text" | "markdown";
export type PdfTextInput = { file: PdfData; pages: number[] | "all"; format: PdfTextFormat };
export type PdfTextOutput = { blob: Blob; pages: number; chars: number };

/* ---------- true redaction (remove content, then flatten) ---------- */
export type RedactBox = {
  /** 1-based page number. */
  page: number;
  /** Fractions of the page, top-left origin. */
  x: number;
  y: number;
  w: number;
  h: number;
};
export type RedactInput = { file: PdfData; boxes: RedactBox[]; scale?: number; quality?: number };
export type RedactOutput = { blob: Blob; pages: number; boxes: number };

/* ---------- AcroForm fill / flatten ---------- */
export type FormFieldType = "text" | "checkbox" | "radio" | "dropdown" | "optionlist" | "button" | "signature" | "unknown";
export type FormFieldInfo = {
  name: string;
  type: FormFieldType;
  value: string | boolean | string[];
  options?: string[];
  readOnly: boolean;
};
export type FormInspectInput = { file: PdfData };
export type FormInspectOutput = { pageCount: number; fields: FormFieldInfo[]; hasXfa: boolean };
export type FormFillInput = {
  file: PdfData;
  values: Record<string, string | boolean | string[]>;
  flatten: boolean;
};
export type FormFillOutput = { blob: Blob; filled: number; skipped: string[] };

/* ---------- protect / unlock (qpdf WASM) ---------- */
export type ProtectPermissions = {
  print: boolean;
  modify: boolean;
  copy: boolean;
  annotate: boolean;
};
export type ProtectInput = {
  file: PdfData;
  userPassword: string;
  ownerPassword: string;
  keyLength: 128 | 256;
  permissions: ProtectPermissions;
};
export type UnlockInput = { file: PdfData; password: string };
export type SecurityOutput = { blob: Blob; encrypted?: boolean };

/* ---------- thumbnail job ---------- */
export type ThumbsInput = { file: PdfData; pages: number[]; width: number };
export type ThumbsOutput = { page: number; blob: Blob }[];
